        summary:
          "Krishna describes divine and demonic qualities, their consequences, and emphasizes following scriptural guidance for spiritual development.",
        teachings:
          "Divine qualities like fearlessness, purity, and honesty lead to liberation. Demonic qualities like pride, anger, and greed lead to bondage. Scriptures provide guidance for proper conduct.",
        moralLesson:
          "We should develop good qualities like kindness, honesty, and self-control, and avoid bad qualities like anger, greed, and pride.",
