            text: "శ్రద్ధయా పరయా తప్తం తపస్తత్త్రివిధం నరైః |\nఅఫలాకాంక్షిభిర్యుక్తైః సాత్త్వికం పరిచక్షతే || 17 ||",
            emotion: "వివరణ",
